--  DDL for Trigger PHASE_AUTO_INCREMENT
--------------------------------------------------------

  CREATE OR REPLACE TRIGGER "CARP"."PHASE_AUTO_INCREMENT" 
BEFORE INSERT ON PHASE
FOR EACH ROW
BEGIN
    IF :NEW.id_phase IS NULL THEN
        SELECT phase_seq.NEXTVAL INTO :NEW.id_phase FROM DUAL;
    END IF;
END;

/
